package org.brightstats.stats;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
public final class LatentInteractionChecks {
 static int checks;static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid latent model accepted");}catch(IllegalArgumentException expected){checks++;}}

 public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);Random random=new Random(81901);int n=240;double[][] data=new double[n][9];double[] offset={2,3,4,-1,2,1,0,5,7};for(int i=0;i<n;i++){double x=random.nextGaussian(),w=.25*x+Math.sqrt(.9375)*random.nextGaussian(),y=.3+.5*x-.25*w+.6*x*w+.7*random.nextGaussian();double[] f={x,w,y};for(int j=0;j<9;j++)data[i][j]=offset[j]+new double[]{1,.9,1.1}[j%3]*f[j/3]+.6*random.nextGaussian();}var predictors=List.of(new LatentInteractionSem.Factor("X",new int[]{0,1,2}),new LatentInteractionSem.Factor("W",new int[]{3,4,5}));var outcome=new LatentInteractionSem.Factor("Y",new int[]{6,7,8});var model=new LatentInteractionSem.Model(predictors,outcome,List.of(new LatentInteractionSem.Interaction(0,1)));var options=new LatentInteractionSem.Options(9,17,400,1,1e-5,1e-10,2e-3,.95);long started=System.nanoTime();var fit=LatentInteractionSem.fit(data,model,options);System.out.println("Latent fit seconds "+((System.nanoTime()-started)/1e9));Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(data));item.add("fit",gson.toJsonTree(fit));require(fit.converged()&&fit.integrationStable()&&fit.locallyIdentified()&&!fit.boundarySolution(),"Latent fit was not regular");require(fit.nonlinearEffects()[0]>.3&&fit.nonlinearEffects()[0]<.9,"Implausible recovered product effect");require(fit.integrationDimensions()==1,"Bilinear model should analytically integrate the other latent dimension");require(fit.parameterCount()==31&&fit.terms().size()==31,"Incorrect free-parameter count");var linearModel=new LatentInteractionSem.Model(predictors,outcome,List.of());var linear=LatentInteractionSem.fit(data,linearModel,options);require(linear.integrationDimensions()==0&&linear.converged(),"Linear likelihood must integrate analytically");var blocks=List.of(new PlsSem.Block("X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("W",new int[]{3,4,5},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{6,7,8},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var normalModel=SemModel.reflective(List.of("X1","X2","X3","W1","W2","W3","Y1","Y2","Y3"),data,blocks,edges,true,true).model();var normalFit=CovarianceSem.fit(data,normalModel,new CovarianceSem.Options(1000,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,true,.95));require(Math.abs(normalFit.logLikelihood()-linear.logLikelihood())<2e-4,"Analytic likelihood differs from ordinary Gaussian SEM");var comparison=LatentInteractionSem.compare(linear,fit);require(comparison.regular()&&comparison.addedParameters()==1&&comparison.statistic()>0&&Double.isFinite(comparison.pValue()),"Invalid nested latent likelihood test");double[] units={.0001,2,.7,3,.5,1.4,2,4,.8};double[][] changed=Matrices.copy(data);for(int row=0;row<n;row++)for(int j=0;j<9;j++)changed[row][j]=20+j+units[j]*data[row][j];var scaled=LatentInteractionSem.fit(changed,model,options);require(scaled.integrationStable()&&Math.abs(scaled.nonlinearEffects()[0]-fit.nonlinearEffects()[0]*units[6]/units[0]/units[3])<1e-3,"Latent product estimate is not unit equivariant");double jacobian=0;for(double unit:units)jacobian+=Math.log(unit);require(Math.abs(scaled.logLikelihood()-fit.logLikelihood()+n*jacobian)<2e-4,"Original-unit likelihood Jacobian is wrong");reject(()->LatentInteractionSem.compare(linear,scaled));reject(()->new LatentInteractionSem.Model(predictors,outcome,List.of(new LatentInteractionSem.Interaction(0,1),new LatentInteractionSem.Interaction(1,0))));reject(()->new LatentInteractionSem.Factor("Bad",new int[]{0,0,1}));reject(()->LatentInteractionSem.fit(Arrays.copyOf(data,30),model,options));double[][] constant=Matrices.copy(data);for(var row:constant)row[0]=1;reject(()->LatentInteractionSem.fit(constant,model,options));Thread.currentThread().interrupt();try{LatentInteractionSem.fit(data,model,options);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}var bootstrap=LatentInteractionSem.bootstrap(data,model,options,new Bootstrap.Options(40,778,.95),null);require(bootstrap.inference().successful()>=32,"Too few regular latent likelihood bootstrap draws");item.add("linear",gson.toJsonTree(linear));item.add("gaussianReference",gson.toJsonTree(normalFit));item.add("comparison",gson.toJsonTree(comparison));item.add("scaled",gson.toJsonTree(scaled));item.add("units",gson.toJsonTree(units));item.add("bootstrap",gson.toJsonTree(bootstrap.inference()));item.addProperty("checks",checks);
JsonArray probes=new JsonArray();for(int scenario=0;scenario<4;scenario++){int q=scenario==0?1:scenario==1?2:3,p=(q+1)*3,rows=scenario==0?400:110;Random generator=new Random(1994+scenario);double[][] sample=new double[rows][p];for(int i=0;i<rows;i++){double common=generator.nextGaussian();double[] x=new double[q];for(int j=0;j<q;j++)x[j]=.3*common+Math.sqrt(.91)*generator.nextGaussian();double y=.2+.7*generator.nextGaussian();for(int j=0;j<q;j++)y+=(.3-.1*j)*x[j];if(scenario<2)for(double value:x)y+=.15*value*value;else if(scenario==2)y+=.2*x[0]*x[1]-.1*x[0]*x[2]+.15*x[1]*x[2];for(int j=0;j<p;j++)sample[i][j]=j*.2+(1+.1*(j%3))*(j/3==q?y:x[j/3])+.7*generator.nextGaussian();}List<LatentInteractionSem.Factor> parents=new ArrayList<>();for(int j=0;j<q;j++)parents.add(new LatentInteractionSem.Factor("P"+j,new int[]{j*3,j*3+1,j*3+2}));List<LatentInteractionSem.Interaction> terms=new ArrayList<>();if(scenario<2)for(int j=0;j<q;j++)terms.add(new LatentInteractionSem.Interaction(j,j));else if(scenario==2)terms.addAll(List.of(new LatentInteractionSem.Interaction(0,1),new LatentInteractionSem.Interaction(0,2),new LatentInteractionSem.Interaction(1,2)));var specification=new LatentInteractionSem.Model(parents,new LatentInteractionSem.Factor("Outcome",new int[]{q*3,q*3+1,q*3+2}),terms);var first=LatentInteractionSem.probe(sample,specification,17,null);double[] theta=first.parameters().clone();int term=0;for(int j=0;j<theta.length;j++)if(first.labels().get(j).startsWith("Product:"))theta[j]=.15*(++term);var evaluated=LatentInteractionSem.probe(sample,specification,17,theta);require(evaluated.dimensions()==(scenario==0?1:scenario==3?0:2),"Incorrect analytic/nonlinear integration partition");JsonObject probe=new JsonObject();probe.add("observations",gson.toJsonTree(sample));probe.add("model",gson.toJsonTree(specification));probe.add("probe",gson.toJsonTree(evaluated));probes.add(probe);}var squareCase=probes.get(0).getAsJsonObject();double[][] squareData=gson.fromJson(squareCase.get("observations"),double[][].class);var squareModel=gson.fromJson(squareCase.get("model"),LatentInteractionSem.Model.class);var squareBootstrap=LatentInteractionSem.bootstrap(squareData,squareModel,options,new Bootstrap.Options(40,884,.90,BootstrapIntervals.Method.BCA,RegressionBootstrap.Convention.STANDARD,true),null);require(squareBootstrap.inference().estimates().stream().anyMatch(e->e.parameter().label().startsWith("Latent product:")&&Double.isFinite(e.lower())),"Latent quadratic full jackknife BCa unavailable");squareCase.add("bootstrap",gson.toJsonTree(squareBootstrap.inference()));squareCase.add("point",gson.toJsonTree(squareBootstrap.point()));
Files.writeString(output.resolve("integration-probes.json"),gson.toJson(probes));
item.addProperty("checks",checks);Files.writeString(output.resolve("interaction.json"),gson.toJson(item));System.out.println("Latent likelihood checks: "+checks);System.out.println("converged="+fit.converged()+" stable="+fit.integrationStable()+" identified="+fit.locallyIdentified()+" iterations="+fit.iterations()+" gamma="+Arrays.toString(fit.nonlinearEffects())+" logLik="+fit.logLikelihood()+" parameterChange="+fit.integrationParameterChange()+" lossChange="+fit.integrationLogLikelihoodChange());}
}
